with feeders as (
    select
        md5(upper('HUB_COVERAGE|' || (HUB_COVERAGE_BK__COVER_CODE))) as HUB_COVERAGE_HK
        , cast(null as varchar) as DEFAULT_SELECTED_INDICATOR
        , cast(null as varchar) as COVERAGE_NAME
        , cast(null as varchar) as RIDER_INDICATOR
        , cast(null as varchar) as COVERAGE_CODE
        , cast(null as varchar) as COVERAGE_TYPE
        , cast(null as varchar) as BENEFIT_TYPE
        , COVER_DESC as COVERAGE_DESCRIPTION
        , 'BJAZ_STARPKG_COVER_MST' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_starpkg_cover_mst') }}
    where (nullif(trim(COVER_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_COVERAGE|' || (HUB_COVERAGE_BK__COVERAGE))) as HUB_COVERAGE_HK
        , cast(null as varchar) as DEFAULT_SELECTED_INDICATOR
        , COVERAGE as COVERAGE_NAME
        , cast(null as varchar) as RIDER_INDICATOR
        , cast(null as varchar) as COVERAGE_CODE
        , cast(null as varchar) as COVERAGE_TYPE
        , cast(null as varchar) as BENEFIT_TYPE
        , cast(null as varchar) as COVERAGE_DESCRIPTION
        , 'BJAZ_GRP_HLT_MEM_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_mem_dtls') }}
    where (md5(normalise(upper(nullif(trim(COVERAGE),''))))) is not null
),

resolved as (
    select
        HUB_COVERAGE_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DEFAULT_SELECTED_INDICATOR end) as DEFAULT_SELECTED_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COVERAGE_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then COVERAGE_NAME end)) as COVERAGE_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RIDER_INDICATOR end) as RIDER_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COVERAGE_CODE end) as COVERAGE_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COVERAGE_TYPE end) as COVERAGE_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BENEFIT_TYPE end) as BENEFIT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then COVERAGE_DESCRIPTION end) as COVERAGE_DESCRIPTION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_COVERAGE_HK
),

hashed as (
    select
        *,
        case when DEFAULT_SELECTED_INDICATOR is not null or COVERAGE_NAME is not null or RIDER_INDICATOR is not null or COVERAGE_CODE is not null or COVERAGE_TYPE is not null or BENEFIT_TYPE is not null or COVERAGE_DESCRIPTION is not null
                     then md5(upper(coalesce(cast(DEFAULT_SELECTED_INDICATOR as varchar), '') || '|' || coalesce(cast(COVERAGE_NAME as varchar), '') || '|' || coalesce(cast(RIDER_INDICATOR as varchar), '') || '|' || coalesce(cast(COVERAGE_CODE as varchar), '') || '|' || coalesce(cast(COVERAGE_TYPE as varchar), '') || '|' || coalesce(cast(BENEFIT_TYPE as varchar), '') || '|' || coalesce(cast(COVERAGE_DESCRIPTION as varchar), '')))
                end as SAT_COVERAGE_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_COVERAGE_HK is not null
  and SAT_COVERAGE_DEFINITION_HASHDIFF is not null
